const rl = require("readline").createInterface({ input: process.stdin });
var iter = rl[Symbol.asyncIterator]();
const readline = async () => (await iter.next()).value;

void (async function () {
  const s = await readline();

  const stack = [];
  for (let c of s) {
    if (c == "<") {
      if (stack.length == 0) continue;
      stack.pop();
    } else {
      stack.push(c);
    }
  }

  let upper = 0;
  let lower = 0;
  let number = 0;
  let non_letter_number = 0;

  const password = [];
  for (let c of stack) {
    password.push(c);

    if (c >= "a" && c <= "z") {
      lower++;
    } else if (c >= "A" && c <= "Z") {
      upper++;
    } else if (c >= "0" && c <= "9") {
      number++;
    } else {
      non_letter_number++;
    }
  }

  if (
    password.length >= 8 &&
    lower >= 1 &&
    upper >= 1 &&
    non_letter_number >= 1
  ) {
    password.push(",true");
  } else {
    password.push(",false");
  }

  console.log(password.join(""));
})();

