#include <stdio.h>
#include <string.h>

#define MAX_SIZE 100000

int main() {
    char s[MAX_SIZE];
    gets(s);

    unsigned long long len = strlen(s);

    char stack[MAX_SIZE];
    int stack_size = 0;

    int upper = 0;
    int lower = 0;
    int number = 0;
    int non_letter_number = 0;

    for (int i = 0; i < len; i++) {
        char key;
        int val;

        if (s[i] == '<') {
            if (stack_size > 0) {
                key = stack[stack_size - 1];
                val = -1;
                stack_size--;
            } else {
                continue;
            }
        } else {
            key = s[i];
            val = 1;
            stack[stack_size++] = s[i];
        }

        if (key >= 'a' && key <= 'z') {
            lower += val;
        } else if (key >= 'A' && key <= 'Z') {
            upper += val;
        } else if (key >= '0' && key <= '9') {
            number += val;
        } else {
            non_letter_number += val;
        }
    }

    stack[stack_size] = '\0';
    if(stack_size >= 8 && lower >= 1 && upper >= 1 && number >= 1 && non_letter_number >= 1) {
        strcat(stack, ",true");
    } else {
        strcat(stack, ",false");
    }

    puts(stack);

    return 0;
}
